 15	// Hook is a logrus hook for redacting information from logs
 16	type Hook struct {
 17		// Messages with a log level not contained in this array
 18		// will not be dispatched. If empty, all messages will be dispatched.
 19		AcceptedLevels []logrus.Level
 20		RedactionList  []string
 21		redactionKeys  []*regexp.Regexp
 22	}
 23	
 24	// Levels returns the user defined AcceptedLevels
 25	// If AcceptedLevels is empty, all logrus levels are returned
 26	func (h *Hook) Levels() []logrus.Level {
 27		if len(h.AcceptedLevels) == 0 {
 28			return logrus.AllLevels
 29		}
 30		return h.AcceptedLevels
 31	}
 32	
 33	// Fire redacts values in an log Entry that match
 34	// with keys defined in the RedactionList
 35	func (h *Hook) Fire(e *logrus.Entry) error {
 36		if err := h.initRedaction(); err != nil {
 37			return err
 38		}
 39		for _, re := range h.redactionKeys {
 40			// Redact based on key matching in Data fields
 41			for k, v := range e.Data {
 42				if re.MatchString(k) {
 43					e.Data[k] = "[REDACTED]"
 44					continue
 45				}
 46	
 47				// Redact values recursively, including nested maps and slices.
 48				e.Data[k] = redactValue(v, re)
 49				}
 50			}
 51	
 52			// Redact based on text matching in the Message field
 53			e.Message = re.ReplaceAllString(e.Message, "$1[REDACTED]$2")
 54		}
 55	
 56		return nil
 57	}
 58	
 59	func redactValue(value interface{}, re *regexp.Regexp) interface{} {
 60		if value == nil {
 61			return nil
 62		}
 63	
 64		rv := reflect.ValueOf(value)
 65		switch rv.Kind() {
 66		case reflect.String:
 67			return re.ReplaceAllString(rv.String(), "$1[REDACTED]$2")
 68		case reflect.Map:
 69			if rv.IsNil() {
 70				return value
 71			}
 72			if rv.Type().Key().Kind() == reflect.String {
 73				redacted := make(map[string]interface{}, rv.Len())
 74				iter := rv.MapRange()
 75				for iter.Next() {
 76					key := iter.Key().String()
 77					if isSensitiveKey(key) || re.MatchString(key) {
 78						redacted[key] = "[REDACTED]"
 79					} else {
 80						redacted[key] = redactValue(iter.Value().Interface(), re)
 81					}
 82				}
 83				return redacted
 84			}
 85			redacted := make(map[interface{}]interface{}, rv.Len())
 86			iter := rv.MapRange()
 87			for iter.Next() {
 88				key := iter.Key().Interface()
 89				if isSensitiveKey(fmt.Sprint(key)) || re.MatchString(fmt.Sprint(key)) {
 90					redacted[key] = "[REDACTED]"
 91				} else {
 92					redacted[key] = redactValue(iter.Value().Interface(), re)
 93				}
 94			}
 95			return redacted
 96		case reflect.Slice, reflect.Array:
 97			containsNestedMap := false
 98			for i := 0; i < rv.Len(); i++ {
 99				kind := rv.Index(i).Kind()
100				if kind == reflect.Map || kind == reflect.Slice || kind == reflect.Array {
101					containsNestedMap = true
102					break
103				}
104			}
105			if containsNestedMap {
106				redacted := make([]interface{}, rv.Len())
107				for i := 0; i < rv.Len(); i++ {
108					redacted[i] = redactValue(rv.Index(i).Interface(), re)
109				}
110				return redacted
111			}
112		}
113	
114		formatted := fmt.Sprint(value)
115		redacted := re.ReplaceAllString(formatted, "$1[REDACTED]$2")
116		if redacted != formatted {
117			return redacted
118		}
119		return value
120	}
121	
122	func isSensitiveKey(key string) bool {
123		key = strings.ToLower(strings.NewReplacer("-", "", "_", "").Replace(key))
124		switch key {
125		case "token", "subsonictoken", "accesstoken", "refreshtoken", "jwt", "secret", "password", "apikey", "authorization", "subsonicsalt":
126			return true
127		default:
128			return false
129		}
130	}
131	
132	func (h *Hook) initRedaction() error {
133		if len(h.redactionKeys) == 0 {
134			for _, redactionKey := range h.RedactionList {
135				re, err := regexp.Compile(redactionKey)
136				if err != nil {
137					return err
138				}
139				h.redactionKeys = append(h.redactionKeys, re)
140			}
141		}
142		return nil
143	}
144	
145	func (h *Hook) redact(msg string) (string, error) {
146		if err := h.initRedaction(); err != nil {
147			return msg, err
148		}
149		for _, re := range h.redactionKeys {
150			msg = re.ReplaceAllString(msg, "$1[REDACTED]$2")
151		}
152	
153		return msg, nil
154	}
