 79	// handleLoginFromHeaders authenticates a request from a trusted reverse proxy.
 80	// A nil result means that the request must continue without a proxy session.
 81	func handleLoginFromHeaders(ds model.DataStore, r *http.Request) map[string]interface{} {
 82		if !validateIPAgainstList(r.RemoteAddr, conf.Server.ReverseProxyWhitelist) {
 83			return nil
 84		}
 85	
 86		header := conf.Server.ReverseProxyUserHeader
 87		if header == "" {
 88			header = "Remote-User"
 89		}
 90		username := strings.TrimSpace(r.Header.Get(header))
 91		if username == "" {
 92			return nil
 93		}
 94	
 95		repo := ds.User(r.Context())
 96		user, err := repo.FindByUsername(username)
 97		if err == model.ErrNotFound {
 98			count, countErr := repo.CountAll()
 99			if countErr != nil {
100				log.Error(r, "Could not count users for reverse proxy login", countErr)
101				return nil
102			}
103			user = &model.User{
104				ID:       uuid.NewString(),
105				UserName: username,
106				Name:     strings.Title(username),
107				IsAdmin:  count == 0,
108			}
109			if err = repo.Put(user); err != nil {
110				log.Error(r, "Could not create user for reverse proxy login", "username", username, err)
111				return nil
112			}
113		} else if err != nil || user == nil {
114			log.Error(r, "Could not find user for reverse proxy login", "username", username, err)
115			return nil
116		}
117	
118		now := time.Now()
119		user.LastLoginAt = &now
120		if err = repo.UpdateLastLoginAt(user.ID); err != nil {
121			log.Error(r, "Could not update LastLoginAt for reverse proxy login", "username", user.UserName, err)
122		}
123	
124		auth.Init(ds)
125		token, err := auth.CreateToken(user)
126		if err != nil {
127			log.Error(r, "Could not create token for reverse proxy login", "username", user.UserName, err)
128			return nil
129		}
130	
131		saltBytes := make([]byte, 3)
132		if _, err = rand.Read(saltBytes); err != nil {
133			log.Error(r, "Could not create Subsonic salt for reverse proxy login", err)
134			return nil
135		}
136		salt := hex.EncodeToString(saltBytes)
137		subsonicToken := fmt.Sprintf("%x", md5.Sum([]byte(user.Password+salt)))
138	
139		payload := map[string]interface{}{
140			"id":            user.ID,
141			"isAdmin":       user.IsAdmin,
142			"name":          user.Name,
143			"username":      user.UserName,
144			"token":         token,
145			"subsonicSalt":  salt,
146			"subsonicToken": subsonicToken,
147		}
148		if conf.Server.EnableGravatar && user.Email != "" {
149			payload["avatar"] = gravatar.Url(user.Email, 50)
150		}
151		return payload
152	}
