154	// validateIPAgainstList matches the request's peer address against a comma-separated
155	// list of IPs or CIDRs. Invalid entries are skipped. Ports are accepted and ignored,
156	// since RemoteAddr contains the connected peer's source port.
157	func validateIPAgainstList(remoteAddr, ipList string) bool {
158		if strings.TrimSpace(ipList) == "" {
159			return false
160		}
161	
162		clientIP, isUnix := parseRemoteIP(remoteAddr)
163		for _, rawEntry := range strings.Split(ipList, ",") {
164			entry := strings.TrimSpace(rawEntry)
165			if entry == "" {
166				continue
167			}
168			if entry == "@" {
169				if isUnix {
170					return true
171				}
172				continue
173			}
174			if isUnix {
175				continue
176			}
177	
178			host := entry
179			if parsedHost, _, err := net.SplitHostPort(entry); err == nil {
180				host = parsedHost
181			}
182			host = strings.Trim(host, "[]")
183	
184			if network, _, err := net.ParseCIDR(host); err == nil {
185				if network.Contains(clientIP) {
186					return true
187				}
188				continue
189			}
190			if allowedIP := net.ParseIP(host); allowedIP != nil && allowedIP.Equal(clientIP) {
191				return true
192			}
193		}
194		return false
195	}
196	
197	func parseRemoteIP(remoteAddr string) (net.IP, bool) {
198		host := remoteAddr
199		if parsedHost, _, err := net.SplitHostPort(remoteAddr); err == nil {
200			host = parsedHost
201		}
202		host = strings.Trim(host, "[]")
203		if ip := net.ParseIP(host); ip != nil {
204			return ip, false
205		}
206		return nil, true
207	}
